    public function up(): void
    {
        if (!Schema::hasTable('blogs') || !Schema::hasTable('blog_translations')) {
            return;
        }

        $links = $this->sanatoriumLinks();
        $now = now();

        $categoryId = DB::table('blog_categories')->where('slug', 'naftalan')->value('id');
        if (!$categoryId) {
            $categoryId = DB::table('blog_categories')->insertGetId(['slug' => 'naftalan', 'status' => 1, 'created_at' => $now, 'updated_at' => $now]);
            foreach ($this->langCodes() as $code) {
                DB::table('blog_category_translations')->insert([
                    'blog_category_id' => $categoryId, 'lang_code' => $code, 'name' => 'Нафталан',
                    'created_at' => $now, 'updated_at' => $now,
                ]);
            }
        }

        $adminId = (int) (DB::table('admins')->orderBy('id')->value('id') ?? 0);
        $offset = 0;

        foreach ($this->articles($links) as $a) {
            if (DB::table('blogs')->where('slug', $a['slug'])->exists()) {
                continue;
            }

            $body = str_replace('#LINKS#', $this->pick($links, $offset, 4), $a['body']) . self::CTA;
            $offset += 2;

            $blogId = DB::table('blogs')->insertGetId([
                'slug' => $a['slug'],
                'image' => '',
                'admin_id' => $adminId,
                'blog_category_id' => $categoryId,
                'views' => 0,
                'status' => 1,
                'show_homepage' => 'no',
                'is_popular' => 'no',
                'tags' => json_encode(array_map(fn ($t) => ['value' => $t], $a['tags']), JSON_UNESCAPED_UNICODE),
                'created_at' => $now,
                'updated_at' => $now,
            ]);

            foreach ($this->langCodes() as $code) {
                $row = [
                    'blog_id' => $blogId,
                    'lang_code' => $code,
                    'title' => $a['title'],
                    'description' => $body,
                    'seo_title' => $a['seo_title'],
                    'seo_description' => $a['seo_description'],
                    'created_at' => $now,
                    'updated_at' => $now,
                ];
                if (Schema::hasColumn('blog_translations', 'short_description')) {
                    $row['short_description'] = $a['short'];
                }
                if (Schema::hasColumn('blog_translations', 'reading_time')) {
                    $row['reading_time'] = '4';
                }
                DB::table('blog_translations')->insert($row);
            }
        }
    }

    private function langCodes(): array
    {
        $codes = Schema::hasTable('languages') ? DB::table('languages')->pluck('lang_code')->all() : [];
        return $codes ?: ['ru', 'en'];
    }

